From 50b11d75e6eb0342846c58a95eb77e83a74115b0 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 23:43:15 +0100
Subject: [PATCH] lockscreen: clear the password field once unlocking starts

The typed password stayed in the field as dots while it was being
checked, which on slow systems shows its length to anyone nearby for
seconds. Now the field is emptied as soon as the password is submitted.

BUG: 455670
---
 desktoppackage/contents/lockscreen/MainBlock.qml | 2 ++
 1 file changed, 2 insertions(+)

diff --git a/desktoppackage/contents/lockscreen/MainBlock.qml b/desktoppackage/contents/lockscreen/MainBlock.qml
index 00140b3313..b20a7d7ffd 100644
--- a/desktoppackage/contents/lockscreen/MainBlock.qml
+++ b/desktoppackage/contents/lockscreen/MainBlock.qml
@@ -51,6 +51,8 @@ SessionManagementScreen {
         //
         // See https://bugreports.qt.io/browse/QTBUG-55460
         loginButton.forceActiveFocus();
+        passwordBox.text = "";
+        passwordBox.text = Qt.binding(() => PasswordSync.password);
         passwordResult(password);
     }

-- 
